/*!
 * Локальная сборка Bootstrap 5 (bundle) без CDN.
 * Реализованы минимально необходимые интерактивные компоненты:
 * закрытие алертов и переключение выпадающих меню. Скрипт работает офлайн.
 */
(function (window, document) {
    "use strict";

    var bootstrap = {};

    // --- Alert -------------------------------------------------------------
    function clearAlert(element) {
        if (!element) { return; }
        element.classList.remove("show");
        element.addEventListener("transitionend", function () {
            element.remove();
        }, { once: true });
        // Резервное удаление, если transition не сработал.
        window.setTimeout(function () {
            if (element.parentNode) { element.parentNode.removeChild(element); }
        }, 400);
    }

    bootstrap.Alert = {
        close: clearAlert,
        getOrCreateInstance: function () { return bootstrap.Alert; }
    };

    // --- Dropdown ----------------------------------------------------------
    bootstrap.Dropdown = {
        toggle: function (trigger) {
            var parent = trigger.closest("[data-bs-toggle='dropdown']") || trigger.parentElement;
            var menu = parent ? parent.querySelector(".dropdown-menu") : null;
            if (menu) {
                menu.classList.toggle("show");
            }
        }
    };

    document.addEventListener("click", function (event) {
        var dismiss = event.target.closest("[data-bs-dismiss='alert']");
        if (dismiss) {
            clearAlert(dismiss.closest(".alert"));
            return;
        }

        var toggle = event.target.closest("[data-bs-toggle='dropdown']");
        if (toggle) {
            event.preventDefault();
            bootstrap.Dropdown.toggle(toggle);
            return;
        }

        // Закрываем открытые меню при клике вне них.
        if (!event.target.closest(".dropdown-menu")) {
            document.querySelectorAll(".dropdown-menu.show").forEach(function (menu) {
                menu.classList.remove("show");
            });
        }
    });

    window.bootstrap = bootstrap;
})(window, document);
